#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# openmail keeps client IDs in its own config.json (via the CLI), not in .env.
ENV_FILE=/dev/null
cd "$(dirname "$0")/.."

CLI=(node --disable-warning=ExperimentalWarning packages/cli/dist/cli.js)
if [[ ! -f packages/cli/dist/cli.js ]]; then
  printf '%s先跑 pnpm build，向导要用 packages/cli/dist/cli.js。%s\n' "$RED" "$RESET"
  exit 1
fi

# configured google|microsoft: is a client already saved in config.json?
configured() {
  node -e '
    const fs = require("node:fs"), path = require("node:path"), os = require("node:os");
    const dir = process.env.OPENMAIL_HOME
      || path.join(os.homedir(), "Library", "Application Support", "openmail");
    const file = path.join(dir, "config.json");
    const config = fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, "utf8")) : {};
    process.exit(config[process.argv[1]] ? 0 : 1);
  ' "$1"
}

DO_GOOGLE=0
DO_MICROSOFT=0
_clear
printf '\n%s%s  openmail OAuth 客户端注册%s\n\n' "$BOLD" "$BLUE" "$RESET"
say "openmail 用你自己注册的 OAuth 客户端登录。这个向导带你在 Google Cloud"
say "和 Azure 控制台里点完注册步骤，再把 client ID 存进 openmail 的 config.json。"
say "数据目录：${OPENMAIL_HOME:-~/Library/Application Support/openmail}"
printf '\n'
if configured google; then note "已配置 Google 客户端。"; fi
if configured microsoft; then note "已配置 Microsoft 客户端。"; fi
confirm "注册 Google 客户端（Gmail）？" && DO_GOOGLE=1
confirm "注册 Microsoft 客户端（个人 outlook.com）？" && DO_MICROSOFT=1
if (( DO_GOOGLE + DO_MICROSOFT == 0 )); then
  say "什么都没选，退出。"
  exit 0
fi

TOTAL_STAGES=$(( DO_GOOGLE * 6 + DO_MICROSOFT * 5 ))

banner "openmail OAuth setup"

if (( DO_GOOGLE )); then
  stage "Google：新建项目"
  say "用你要同步的 Gmail 账号登录 Google Cloud。"
  open_url "https://console.cloud.google.com/projectcreate"
  step "Project name 填 openmail，Location 保持默认，点 Create。"
  step "创建完成后，在页面顶部的项目选择器里切到 openmail。"
  note "后面每一页都要确认顶部选中的是 openmail 项目。"
  pause "项目建好并已切换后按 Enter"

  stage "Google：启用 Gmail API"
  open_url "https://console.cloud.google.com/apis/library/gmail.googleapis.com"
  step "确认顶部项目是 openmail，点 Enable。"
  note "按钮已经变成 Manage 说明之前启用过，直接继续。"
  pause "启用后按 Enter"

  stage "Google：Branding"
  open_url "https://console.cloud.google.com/auth/branding"
  step "第一次进入会显示 Get started，点它。"
  step "App name 填 openmail，User support email 选你的邮箱。"
  step "Audience 选 External。"
  step "Contact information 填你的邮箱，勾选同意条款，点 Create。"
  pause "完成后按 Enter"

  stage "Google：Audience 切到 In production"
  open_url "https://console.cloud.google.com/auth/audience"
  say "停在 Testing 的话，refresh token 7 天后过期，每周要重新登录。"
  step "Publishing status 下点 Publish app，确认。状态变成 In production。"
  note "不用提交审核。登录时 Google 会显示「此应用未经验证」，点「高级 → 继续」。"
  pause "状态是 In production 后按 Enter"

  stage "Google：创建 Desktop 客户端"
  open_url "https://console.cloud.google.com/auth/clients/create"
  step "Application type 选 Desktop app，Name 填 openmail desktop，点 Create。"
  step "弹窗里显示 Client ID 和 Client secret，也可以点 Download JSON 留底。"
  ask GOOGLE_CLIENT_ID "粘贴 Client ID（以 .apps.googleusercontent.com 结尾）:"
  while [[ "$GOOGLE_CLIENT_ID" != *.apps.googleusercontent.com ]]; do
    warn "格式不对，Client ID 应以 .apps.googleusercontent.com 结尾。"
    ask GOOGLE_CLIENT_ID "重新粘贴 Client ID:"
  done
  ask_secret GOOGLE_CLIENT_SECRET "粘贴 Client secret（输入不回显）:"
  while [[ -z "$GOOGLE_CLIENT_SECRET" ]]; do
    ask_secret GOOGLE_CLIENT_SECRET "Client secret 不能为空，重新粘贴:"
  done

  stage "Google：保存并登录 Gmail"
  "${CLI[@]}" config google --client-id "$GOOGLE_CLIENT_ID" --client-secret "$GOOGLE_CLIENT_SECRET"
  if confirm "现在登录 Gmail？会打开 Google 的授权页"; then
    "${CLI[@]}" accounts add gmail || SKIPPED+=("Gmail 登录失败，之后跑：pnpm cli accounts add gmail")
  else
    SKIPPED+=("登录 Gmail：pnpm cli accounts add gmail，或在 app 里添加")
  fi
  pause "按 Enter 继续"
fi

if (( DO_MICROSOFT )); then
  stage "Microsoft：注册应用"
  say "用你的个人 Microsoft 账号（outlook.com / hotmail / live）登录。"
  open_url "https://portal.azure.com/#view/Microsoft_AAD_RegisteredApps/CreateApplicationBlade"
  step "Name 填 openmail。"
  step "Supported account types 选 Personal Microsoft accounts only。"
  step "Redirect URI：平台选 Public client/native (mobile & desktop)，值填 http://localhost"
  step "点 Register。"
  note "Azure 不接受 http://127.0.0.1。http://localhost 对任意端口都能回调。"
  warn "如果提示个人账号不能在目录外注册应用，先免费开一个 Azure 账号，它会建默认目录。"
  pause "注册完成后按 Enter"

  stage "Microsoft：复制 client ID"
  step "注册后停在 Overview 页。复制 Application (client) ID。"
  ask MICROSOFT_CLIENT_ID "粘贴 Application (client) ID:"
  while [[ ! "$MICROSOFT_CLIENT_ID" =~ ^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$ ]]; do
    warn "格式不对，应该是 GUID，比如 1b2c3d4e-0000-1111-2222-333344445555。"
    ask MICROSOFT_CLIENT_ID "重新粘贴:"
  done

  stage "Microsoft：API 权限"
  step "左侧点 API permissions → Add a permission → Microsoft Graph → Delegated permissions。"
  step "勾选 Mail.Read、User.Read、offline_access，点 Add permissions。"
  note "User.Read 通常已经默认在列表里。个人账户不需要管理员同意。"
  pause "三个权限都在列表里后按 Enter"

  stage "Microsoft：打开公共客户端"
  step "左侧点 Authentication。"
  step "确认 Redirect URI 里有 http://localhost（Mobile and desktop applications 下）。"
  step "Allow public client flows 切到 Yes，点 Save。"
  note "公共客户端用 PKCE，没有 secret。"
  pause "保存后按 Enter"

  stage "Microsoft：保存并登录 Outlook"
  "${CLI[@]}" config microsoft --client-id "$MICROSOFT_CLIENT_ID"
  if confirm "现在登录 Outlook？会打开 Microsoft 的授权页"; then
    "${CLI[@]}" accounts add outlook || SKIPPED+=("Outlook 登录失败，之后跑：pnpm cli accounts add outlook")
  else
    SKIPPED+=("登录 Outlook：pnpm cli accounts add outlook，或在 app 里添加")
  fi
  pause "按 Enter 继续"
fi

finish
"${CLI[@]}" accounts list || true
